    function hipsparseSbsric02_bufferSize_raw(handle, dirA, mb, nnzb, descrA, bsrValA, bsrRowPtrA, &
                                              bsrColIndA, blockDim, info, pBufferSizeInBytes) &
       result(Sbsric02_bufferSize_raw) &
#ifdef USE_CUDA_NAMES
       bind(C, name="cusparseSbsric02_bufferSize")
#else
       bind(C, name="hipsparseSbsric02_bufferSize")
#endif
       import :: c_ptr, c_int
       type(c_ptr), value :: handle
