       integer(c_int), value :: m
       integer(c_int), value :: n
       integer(c_int), value :: nnz
       type(c_ptr), value :: descrA
       type(c_ptr), value :: csrRowPtr
       type(c_ptr), value :: csrColInd
       type(c_ptr), value :: P
       type(c_ptr), value :: pBuffer
